import { useEffect, useId, useRef, useState } from 'react';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { EmptyState } from '@kerfjs/ui/empty-state';
import '@kerfjs/ui/layout.css';
import './command-palette.css';

// Available frozen package guidance exposes DialogHeader and EmptyState,
// but no command palette contract. It is not a complete export catalog;
// package absence cannot be established without inspecting that catalog.
// This is application-owned command-palette semantics, not a claimed Kerf export.
export type Command = { id: string; label: string; group: string; run: () => void };
export function CommandPalette({ open, commands, recentIds, onRecentChange, onClose }: {
  open: boolean; commands: Command[]; recentIds: string[];
  onRecentChange: (ids: string[]) => void; onClose: () => void;
}) {
  const dialog = useRef<HTMLDialogElement>(null);
  const input = useRef<HTMLInputElement>(null);
  const id = useId();
  const [query, setQuery] = useState('');
  const [active, setActive] = useState<string | null>(null);
  const recent = recentIds.map(key => commands.find(command => command.id === key))
    .filter((command): command is Command => !!command);
  const normalized = query.trim().toLocaleLowerCase();
  const matching = commands.filter(command => command.label.toLocaleLowerCase().includes(normalized));
  const groups = normalized ? [...new Set(matching.map(command => command.group))].map(group => ({
    name: group, commands: matching.filter(command => command.group === group),
  })) : [
    ...(recent.length ? [{ name: 'Recent', commands: recent }] : []),
    ...[...new Set(commands.map(command => command.group))].map(group => ({
      name: group, commands: commands.filter(command => command.group === group && !recentIds.includes(command.id)),
    })).filter(group => group.commands.length),
  ];
  const flat = groups.flatMap(group => group.commands);
  const current = flat.find(command => command.id === active) ?? flat[0];
  const optionId = (command: Command) => id + '-option-' + encodeURIComponent(command.id);
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    const element = dialog.current!;
    if (open) { setQuery(''); setActive(null); if (!element.open) element.showModal(); input.current?.focus(); }
    else if (element.open) element.close();
    return () => { if (element.open) element.close(); if (previous?.isConnected) previous.focus(); };
  }, [open]);
  useEffect(() => { if (current) document.getElementById(optionId(current))?.scrollIntoView({ block: 'nearest' }); }, [current?.id]);
  function execute(command: Command) {
    onRecentChange([command.id, ...recentIds.filter(key => key !== command.id)].slice(0, 10));
    onClose();
    command.run();
  }
  return <dialog ref={dialog} className="kui-layout command-palette" aria-labelledby={id + '-title'}
    onCancel={event => { event.preventDefault(); onClose(); }}>
    <DialogHeader title={<span id={id + '-title'}>Run a command</span>} />
    <div className="kui-dialog-body command-body">
      <label htmlFor={id + '-query'}>Search commands</label>
      <input ref={input} id={id + '-query'} role="combobox" aria-autocomplete="list"
        aria-expanded="true" aria-controls={id + '-results'}
        aria-activedescendant={current ? optionId(current) : undefined}
        value={query} onChange={event => { setQuery(event.target.value); setActive(null); }}
        onKeyDown={event => {
          if (event.nativeEvent.isComposing) return;
          const index = flat.findIndex(command => command.id === current?.id);
          if (['ArrowDown', 'ArrowUp'].includes(event.key)) {
            event.preventDefault();
            if (flat.length) setActive(flat[(index + (event.key === 'ArrowDown' ? 1 : -1) + flat.length) % flat.length].id);
          } else if (event.key === 'Enter' && current) { event.preventDefault(); execute(current); }
        }} />
      <div id={id + '-results'} role="listbox" aria-label="Commands" className="command-results">
        {groups.map((group, groupIndex) => <div key={group.name} role="group" aria-labelledby={id + '-group-' + groupIndex}>
          <div id={id + '-group-' + groupIndex}>{group.name}</div>
          {group.commands.map(command => <div key={command.id} id={optionId(command)} role="option"
            aria-selected={current?.id === command.id} className="command-option"
            onPointerDown={event => event.preventDefault()} onClick={() => execute(command)}>
            {current?.id === command.id && <span aria-hidden="true">› </span>}{command.label}
          </div>)}
        </div>)}
      </div>
      {flat.length === 0 && <EmptyState title="No commands found" description="Try another search." />}
      <p role="status" aria-live="polite">{flat.length} commands available</p>
      <button type="button" onClick={onClose}>Cancel</button>
    </div>
  </dialog>;
}
// Host application owns command registration, permissions, execution and recent
// history persistence. Confirm primitive prop declarations during integration.

