.command-palette { padding: 0; inline-size: min(36rem, calc(100vw - 2rem)); max-block-size: calc(100dvh - 2rem); overflow: auto; }
.command-body { min-inline-size: 0; overflow-wrap: anywhere; }
.command-body input { box-sizing: border-box; inline-size: 100%; min-block-size: 2.75rem; }
.command-option { min-block-size: 2.75rem; display: flex; align-items: center; cursor: pointer; }
.command-option[aria-selected="true"] { outline: 2px solid currentColor; outline-offset: -2px; font-weight: bold; }
.command-palette :focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
